window.REPORT_PRELOAD_CACHE["RKLB.html"] = {"version":"6f98b1179e1fd32aeef48b03447c79e3779c5c59c02ffa857b76c795b2288fd2","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Rocket Lab (NASDAQ: RKLB) 深度研究报告：从小型商业发射王者到端到端太空系统与中大型火箭新星</title>\n  <!-- Tailwind CSS -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <!-- Chart.js -->\n  <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n  <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n            mono: ['JetBrains Mono', 'monospace'],\n          },\n          colors: {\n            navy: {\n              950: '#0B1120',\n              900: '#0F172A',\n              800: '#1E293B',\n              700: '#334155',\n            },\n            crimson: {\n              300: '#FDA4AF',\n              400: '#FB7185',\n              500: '#F43F5E',\n              600: '#E11D48',\n              700: '#BE123C',\n            },\n            accent: {\n              500: '#3B82F6',\n              600: '#2563EB',\n            },\n            teal: {\n              500: '#0D9488',\n              600: '#0F766E',\n            }\n          }\n        }\n      }\n    }\n  </script>\n\n  <style>\n    /* 自定义滚动条与机构研报细节排版 */\n    ::-webkit-scrollbar {\n      width: 6px;\n      height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n      background: transparent;\n    }\n    ::-webkit-scrollbar-thumb {\n      background: #94A3B8;\n      border-radius: 3px;\n    }\n    .dark ::-webkit-scrollbar-thumb {\n      background: #475569;\n    }\n\n    /* 打印友好优化 */\n    @media print {\n      #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n        display: none !important;\n      }\n      main {\n        margin-left: 0 !important;\n        padding: 0 !important;\n      }\n      section {\n        break-inside: avoid;\n      }\n    }\n\n    /* 卡片悬浮微光 */\n    .report-card {\n      transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n    }\n    .report-card:hover {\n      transform: translateY(-2px);\n    }\n\n    /* 侧边导航激活态 */\n    .nav-link.active {\n      background: linear-gradient(90deg, rgba(225, 29, 72, 0.28) 0%, rgba(244, 63, 94, 0.06) 100%);\n      border-left: 3px solid #E11D48;\n      color: #FFFFFF;\n      font-weight: 600;\n    }\n  </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#0F172A] dark:bg-navy-950 dark:text-[#F1F5F9] antialiased selection:bg-crimson-600 selection:text-white transition-colors duration-200\">\n\n  <!-- 顶部全局阅读进度条 (Rocket Lab 航天绯红主色 #E11D48) -->\n  <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n    <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-crimson-600 via-crimson-500 to-amber-500 w-0 transition-all duration-150\"></div>\n  </div>\n\n  <!-- 移动端顶部导航栏 -->\n  <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n    <div class=\"flex items-center space-x-2.5\">\n      <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-crimson-600 to-crimson-700 flex items-center justify-center font-extrabold text-white text-xs shadow border border-white/15\">\n        RKLB\n      </div>\n      <div>\n        <div class=\"text-[11px] text-crimson-300 font-semibold tracking-wider uppercase\">NASDAQ: RKLB · Equity Research</div>\n        <div class=\"text-sm font-bold leading-tight\">Rocket Lab 深度投资研究报告</div>\n      </div>\n    </div>\n    <div class=\"flex items-center space-x-2\">\n      <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n        <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n        <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n      </button>\n      <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n      </button>\n    </div>\n  </header>\n\n  <!-- 移动端折叠抽屉菜单 -->\n  <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n    <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n    <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n      <div>\n        <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n          <span class=\"font-bold text-white text-base\">RKLB 研报目录导航</span>\n          <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n          </button>\n        </div>\n        <ul class=\"mt-4 space-y-1.5 text-sm\">\n          <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构</a></li>\n          <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n          <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n          <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康度与估值体系</a></li>\n          <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与三情景推演</a></li>\n          <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 风险配置与季度跟踪 KPI</a></li>\n        </ul>\n      </div>\n      <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n        <p>全球商业航天与前沿科技研究组</p>\n        <p class=\"mt-1\">数据基准：2026年11月 (FY25 / FY26E)</p>\n      </div>\n    </nav>\n  </div>\n\n  <!-- 桌面端左侧固定侧边导航栏 (宽 280px, Deep Navy #0F172A) -->\n  <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n    <div>\n      <!-- 机构品牌头 -->\n      <div class=\"p-5 border-b border-slate-800/80\">\n        <div class=\"flex items-center space-x-3\">\n          <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-crimson-600 to-crimson-700 flex items-center justify-center text-white font-extrabold text-xs shadow-lg shadow-crimson-600/30 border border-white/15\">\n            RKLB\n          </div>\n          <div>\n            <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-crimson-300 bg-crimson-600/20 px-2 py-0.5 rounded border border-crimson-500/30\">NASDAQ: RKLB</span>\n            <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">Rocket Lab 深度研报</h2>\n          </div>\n        </div>\n        <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n          全球商用发射“非 SpaceX 第二极” · 端到端太空系统与 Neutron 中型火箭领军者\n        </p>\n      </div>\n\n      <!-- 侧边栏关键财务与运营快照卡片 -->\n      <div class=\"px-5 py-3 bg-navy-950/85 border-b border-slate-800/80 space-y-1.5 text-xs\">\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">2025 实际营收</span>\n          <span class=\"font-mono font-bold text-white\">~$602M <span class=\"text-crimson-400\">(+38% YoY)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">2026E 共识营收</span>\n          <span class=\"font-mono font-bold text-teal-400\">~$880M–$920M</span>\n        </div>\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">在手订单 Backlog</span>\n          <span class=\"font-mono font-bold text-amber-400\">&gt;$1.1B <span class=\"text-slate-400\">(~70% 太空系统)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">Electron 累计发射</span>\n          <span class=\"font-mono font-bold text-white\">&gt;70 次 <span class=\"text-emerald-400\">(全球第二)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n          <span class=\"text-slate-400\">Neutron & 现金储备</span>\n          <span class=\"font-mono font-bold text-crimson-300\">13t 商用推进 · ~$1.0B+</span>\n        </div>\n      </div>\n\n      <!-- 六个核心章节目录导航 -->\n      <div class=\"px-3 py-3 overflow-y-auto max-h-[calc(100vh-360px)]\">\n        <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节 · 2026年11月</div>\n        <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n          <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-crimson-400 mr-2\">01</span>业务与收入架构</span>\n          </a>\n          <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n          </a>\n          <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局横向对比</span>\n          </a>\n          <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康度与估值体系</span>\n          </a>\n          <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与三情景推演</span>\n          </a>\n          <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>风险配置与季度跟踪 KPI</span>\n          </a>\n        </nav>\n      </div>\n    </div>\n\n    <!-- 侧边栏底部工具栏 -->\n    <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n      <div class=\"flex items-center justify-between\">\n        <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n        <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n          <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n          <svg class=\"w-3.5 h-3.5 text-crimson-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n          <span class=\"dark:hidden\">深色护眼模式</span>\n          <span class=\"hidden dark:inline\">机构亮色模式</span>\n        </button>\n      </div>\n      <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-crimson-600 hover:bg-crimson-700 text-white text-xs font-bold transition shadow-sm\">\n        <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n        <span>打印 / 导出 PDF 研报</span>\n      </button>\n    </div>\n  </aside>\n\n  <!-- 主内容区 -->\n  <main class=\"lg:ml-[280px] min-h-screen\">\n    <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n      <!-- =========================================================\n           顶部机构研报核心摘要 Hero 看板 (Executive Overview)\n      ========================================================= -->\n      <div class=\"space-y-6\">\n        <div class=\"flex flex-wrap items-center justify-between gap-3 text-xs text-slate-500 dark:text-slate-400\">\n          <div class=\"flex flex-wrap items-center gap-2\">\n            <span class=\"px-2.5 py-1 rounded-md bg-crimson-600/15 text-crimson-700 dark:text-crimson-300 font-bold border border-crimson-500/30\">评级：强烈看多 / 全球商业航天稀缺核心资产</span>\n            <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">主线：非 SpaceX 第二极 × 端到端太空系统 × Neutron 盈利拐点</span>\n          </div>\n          <div class=\"flex items-center space-x-3 font-mono\">\n            <span>覆盖基准：2026年11月 (FY25 / FY26E)</span>\n            <span>NASDAQ: RKLB</span>\n          </div>\n        </div>\n\n        <!-- Hero 标题卡片 -->\n        <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-[#1A1625] to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n          <div class=\"absolute inset-0 opacity-15 pointer-events-none\" style=\"background-image: radial-gradient(#E11D48 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n          <div class=\"relative z-10\">\n            <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-crimson-600/20 border border-crimson-500/40 text-crimson-300 text-xs font-semibold mb-4\">\n              <span class=\"w-2 h-2 rounded-full bg-crimson-500 animate-pulse\"></span>\n              <span>CORE THESIS · 唯一兼具“高频轨道发射 + 垂直卫星制造”的上市端到端太空主承包商</span>\n            </div>\n            <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n              Rocket Lab (NASDAQ: RKLB) 深度研究报告：从小型商业发射王者到端到端太空系统与中大型火箭新星\n            </h1>\n            <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n              Rocket Lab 已成功打破“纯火箭发射公司难以盈利”的传统桎梏，进化为全球除 SpaceX 外最成熟、交付确定性最高的<strong>端到端太空基础设施巨头</strong>。公司 2025 年营收攀升至 <strong class=\"text-crimson-300\">~$602M (+38% YoY)</strong>，2026E 共识营收剑指 <strong class=\"text-white\">~$880M–$920M (+48% YoY)</strong>，在手订单（Backlog）稳居 <strong class=\"text-amber-400\">&gt;$1.1B</strong>。通过 <strong class=\"text-teal-400\">Space Systems（太空系统与卫星制造，占营收 ~70%+）</strong>构建起高粘性国防与商业星座现金流底座，叠加 <strong class=\"text-white\">Electron（累计发射超 70 次）</strong>绝对统治小型专享发射市场，以及 13 吨级可复用中型火箭 <strong class=\"text-crimson-300\">Neutron</strong> 迈向商业化放量，公司正迎来自研投入达峰向 EBITDA 与自由现金流转正的历史性盈利拐点。\n            </p>\n\n            <!-- 核心投资结论三栏摘要 -->\n            <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">稀缺“非 SpaceX 第二极”</div>\n                <div class=\"text-white font-semibold\">美国国防部（USSF/SDA）与商业巨型星座迫切需要独立于 SpaceX 的第二发射与卫星供应链</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">太空系统占比超 70%</div>\n                <div class=\"text-teal-300 font-semibold\">手握 SDA $515M+ 军用卫星主合同及 &gt;70% 卫星核心部件自产能力，平滑发射波动</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">~$1.0B+ 现金护航盈利拐点</div>\n                <div class=\"text-crimson-300 font-semibold\">充沛流动性完全覆盖 Neutron 研发至商业首飞，2026–2027 迎 EBITDA 与 FCF 强势转正</div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- 4个核心 KPI 卡片 -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4\">\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>2025 / 2026E 营业收入</span>\n              <span class=\"p-1.5 rounded-lg bg-crimson-600/15 text-crimson-600 dark:text-crimson-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$602M</span>\n              <span class=\"text-xs font-bold text-crimson-600 dark:text-crimson-300 bg-crimson-600/15 px-2 py-0.5 rounded\">26E ~$900M</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              2021–2026E 五年复合增速高达 ~71%，由卫星总线交付放量与高频发射双轮驱动。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>在手订单 Backlog & 结构</span>\n              <span class=\"p-1.5 rounded-lg bg-amber-500/15 text-amber-600 dark:text-amber-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">&gt;$1.1B</span>\n              <span class=\"text-xs font-bold text-amber-600 dark:text-amber-400 bg-amber-500/15 px-2 py-0.5 rounded\">太空系统 ~70%</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              涵盖 SDA 18颗国防传输层卫星（$515M+）及数十发 Electron / HASTE 商业与军方排期。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>Electron 累计发射 & 市场地位</span>\n              <span class=\"p-1.5 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">&gt;70次</span>\n              <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/15 px-2 py-0.5 rounded\">小型商业发射第一</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              仅次于 SpaceX 的全球第二高频商业轨道发射商，年发射节奏迈向 20+ 次以上。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>现金储备与 Neutron 战略杠杆</span>\n              <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~$1.0B+</span>\n              <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">Neutron 单次 ~$55M</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              充裕现金与有价证券无惧资本开支峰值，Neutron 13吨级可复用火箭打开 6 倍客单价弹性。\n            </p>\n          </div>\n        </div>\n      </div>\n\n      <!-- =========================================================\n           01. 业务与收入架构 (Business & Revenue Architecture)\n      ========================================================= -->\n      <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-crimson-600 dark:text-crimson-400\">Section 01 · Business & Revenue Architecture</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">01. 业务与收入架构：Space Systems 压舱石与双火箭发射矩阵</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">双引擎模型：Space Systems (~70%+) + Launch Services (~30%)</span>\n        </div>\n\n        <!-- 三大核心业务模块卡片 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n          <!-- 模块 1：Space Systems -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2.5\">\n              <span class=\"px-2.5 py-0.5 rounded bg-teal-500/15 text-teal-600 dark:text-teal-400 text-xs font-bold\">第一增长极 · 核心利润引擎</span>\n              <span class=\"font-mono text-xs font-bold text-slate-700 dark:text-slate-300\">占营收 ~70%+</span>\n            </div>\n            <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">Space Systems：端到端卫星制造与核心分系统</h3>\n            <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n              <strong>① 整星平台制造：</strong>覆盖 Photon、Explorer（深空探测）、Pioneer 及 Lightning（国防通信）四大卫星总线，斩获美国太空发展局（SDA）<strong>$515M+</strong> 18颗传输层卫星主合同及 Globalstar 等商业星座大单；<br>\n              <strong>② 航天核心零部件：</strong>行业标准的卫星分离系统（Lightband）、反作用飞轮、星敏感器（Sinclair）及宇航级三结砷化镓太阳翼（SolAero），为全球几乎所有头部星座供货。\n            </p>\n          </div>\n\n          <!-- 模块 2：Electron & HASTE -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-crimson-600 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2.5\">\n              <span class=\"px-2.5 py-0.5 rounded bg-crimson-600/15 text-crimson-700 dark:text-crimson-300 text-xs font-bold\">小型轨道发射绝对霸主</span>\n              <span class=\"font-mono text-xs font-bold text-slate-700 dark:text-slate-300\">$7.5M–$8.5M/次</span>\n            </div>\n            <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">Electron 电子号 & HASTE 高超音速测试</h3>\n            <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n              <strong>① Electron 专享发射：</strong>300kg 近地轨道运力，全球唯一实现高频商业常态化运行的小型火箭（累计发射超 70 次），以精准轨道倾角定制与 24 小时快速响应成为商业卫星补网及 NASA 科研首选；<br>\n              <strong>② HASTE 亚轨道高超音速：</strong>基于 Electron 衍生的军用测试载具，在弗吉尼亚州 Wallops 基地发射，精准卡位美国国防部（DIU/MDA）高超音速武器测试刚需，单次毛利显著高于标准发射。\n            </p>\n          </div>\n\n          <!-- 模块 3：Neutron 中型可复用火箭 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-amber-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2.5\">\n              <span class=\"px-2.5 py-0.5 rounded bg-amber-500/15 text-amber-700 dark:text-amber-400 text-xs font-bold\">第二增长曲线 · 13吨级重器</span>\n              <span class=\"font-mono text-xs font-bold text-slate-700 dark:text-slate-300\">~$50M–$55M/次</span>\n            </div>\n            <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">Neutron 中子号：切入巨型星座部署与国家发射</h3>\n            <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n              专为大规模星座组网与国家安全载荷打造的中型部分可复用运载火箭：采用全球首创全碳纤维复合材料箭体结构、一体化“河马嘴（Hungry Hippo）”固定整流罩及 9 台自研 <strong>Archimedes 液氧甲烷发动机</strong>。近地轨道运力高达 <strong>13,000 kg</strong>，单次报价 <strong>$50M–$55M</strong>（约为 Electron 的 6.5 倍），且成功入选美国太空军 <strong>NSSL Lane 1</strong> 国家级发射供应商名录。\n            </p>\n          </div>\n        </div>\n\n        <!-- 交互式 Chart.js 双视图面板 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2021–2027E 营收结构演进（Space Systems vs. Launch Services 堆叠 + GAAP 毛利率）</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">营收从 2021 年 $62M 跃升至 2026E ~$900M 及 2027E ~$1.35B（含 Neutron 商业化放量），毛利率迈向 35%+</p>\n            </div>\n            <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n              <button onclick=\"switchBizChart('trajectory')\" id=\"btn-chart-traj\" class=\"px-3 py-1.5 rounded-md font-semibold bg-white dark:bg-navy-700 text-crimson-600 dark:text-crimson-300 shadow-sm transition\">2021–2027E 营收结构与毛利率</button>\n              <button onclick=\"switchBizChart('backlog')\" id=\"btn-chart-backlog\" class=\"px-3 py-1.5 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">在手订单 Backlog 与供应链自给拆解</button>\n            </div>\n          </div>\n          <div class=\"relative h-72 w-full\">\n            <canvas id=\"bizArchitectureChart\"></canvas>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           02. 行业地位与护城河 (Industry Position & Economic Moat)\n      ========================================================= -->\n      <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Industry Position & Economic Moat</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">02. 行业地位与四重核心护城河：端到端航天闭环与稀缺生态位</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：宽护城河 (Wide Moat · 高工程壁垒 × 军工准入牌照 × 垂直自产)</span>\n        </div>\n\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n          <!-- 左侧：四重核心壁垒卡片网格 -->\n          <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <!-- 壁垒 1 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-crimson-600/15 text-crimson-600 dark:text-crimson-300 flex items-center justify-center font-bold text-sm\">01</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">Electron 高频发射可靠性与飞行履历壁垒</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                商业航天极度看重“飞行验证（Flight Heritage）”。Electron 累计成功发射超 70 次、将逾 200 颗卫星送入轨道，是全球除 SpaceX 猎鹰九号外发射频次最高的商业火箭，彻底甩开 Astra、Virgin Orbit 等破产或停滞的小型火箭竞争对手。\n              </p>\n            </div>\n\n            <!-- 壁垒 2 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">02</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">超 70% 卫星部件自给的端到端垂直供应链</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                通过精准并购 Sinclair Interplanetary、Planetary Systems、SolAero 与 ASI，Rocket Lab 实现卫星太阳翼、分离器、飞轮、星敏与飞行软件 <strong>&gt;70% 内部自产</strong>。这不仅缩短交付周期、将 Space Systems 毛利率推升至 35%+，更让竞争对手在制造自身卫星时也不得不向 RKLB 采购关键零件。\n              </p>\n            </div>\n\n            <!-- 壁垒 3 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-accent-500/15 text-accent-600 dark:text-accent-400 flex items-center justify-center font-bold text-sm\">03</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">国防安全顶级准入资质与深空科研背书</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                拥有美军最高机密级交付资质与新西兰 Mahia + 美国弗吉尼亚 Wallops 双发射场布局：已成功执行 NASA 月球 CAPSTONE 探路者、火星 ESCAPADE 双探测器研制，并斩获五角大楼 SDA 卫星星座及美国太空军 NSSL Lane 1 国家安全发射资格。\n              </p>\n            </div>\n\n            <!-- 壁垒 4 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-amber-500/15 text-amber-600 dark:text-amber-400 flex items-center justify-center font-bold text-sm\">04</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">Neutron 卡位“非 SpaceX 第二选择”稀缺红利</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                由于 SpaceX 自身运营庞大的 Starlink 星链网络，Amazon Kuiper、OneWeb、Telesat 等商业星座巨头以及美国军方存在强烈的“去单一供应商依赖”诉求。Neutron 凭借 13 吨运力与可复用低成本，成为商业星座与政府发射最现实的第二支柱。\n              </p>\n            </div>\n          </div>\n\n          <!-- 右侧：五维护城河量化雷达图 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">全球商业航天竞争格局五维量化雷达图</h3>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">Rocket Lab vs. SpaceX vs. 传统航天巨头 vs. 新兴中小型发射商（满分 10 分）</p>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"moatRadarChart\"></canvas>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           03. 同行竞争格局横向对比 (Competitive Landscape & Peer Matrix)\n      ========================================================= -->\n      <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-crimson-600 dark:text-crimson-400\">Section 03 · Global Aerospace Competitive Matrix</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">03. 同行竞争格局横向对比：全栈航天能力与商业执行力领跑</h2>\n          </div>\n          <!-- 交互式筛选按钮 -->\n          <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n            <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-crimson-600 text-white shadow-sm transition\">全部阵营</button>\n            <button onclick=\"filterCompetitors('launch')\" data-filter=\"launch\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">发射服务竞争者</button>\n            <button onclick=\"filterCompetitors('prime')\" data-filter=\"prime\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">端到端太空与国防承包商</button>\n            <button onclick=\"filterCompetitors('satellite')\" data-filter=\"satellite\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">卫星制造与组件商</button>\n          </div>\n        </div>\n\n        <!-- 横向对比矩阵表格 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-left border-collapse\">\n              <thead>\n                <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n                  <th class=\"py-4 px-5 min-w-[190px]\">竞争主体与代码</th>\n                  <th class=\"py-4 px-4 min-w-[140px]\">核心定位</th>\n                  <th class=\"py-4 px-4 min-w-[145px]\">运载能力与发射频次</th>\n                  <th class=\"py-4 px-4 min-w-[145px]\">垂直整合程度</th>\n                  <th class=\"py-4 px-4 min-w-[130px]\">在手订单 / 营收规模</th>\n                  <th class=\"py-4 px-5 min-w-[220px]\">估值与核心战略优劣势</th>\n                </tr>\n              </thead>\n              <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n                <!-- 行 1：Rocket Lab 行业基准 -->\n                <tr data-category=\"core\" class=\"bg-crimson-600/5 dark:bg-crimson-600/10 font-medium\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"flex items-center space-x-2\">\n                      <span class=\"px-2 py-0.5 rounded bg-crimson-600 text-white text-[10px] font-bold\">研究标的</span>\n                      <span class=\"font-bold text-slate-900 dark:text-white\">Rocket Lab (RKLB)</span>\n                    </div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">端到端商业航天上市龙头</div>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-800 dark:text-slate-200\">高频发射 + 整星/部件制造</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-900 dark:text-white\">Electron 300kg (&gt;70次)<br><span class=\"text-xs text-crimson-600 dark:text-crimson-400\">Neutron 13t 推进中</span></td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-teal-500/15 text-teal-700 dark:text-teal-300\">&gt;70% 卫星组件自产</span>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-800 dark:text-slate-200\">Backlog &gt;$1.1B<br><span class=\"text-xs text-slate-500\">26E Rev ~$900M</span></td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>核心优势：</strong>公开市场唯一“迷你版 SpaceX”全栈标的，兼具高成长与军工国防背书。\n                  </td>\n                </tr>\n\n                <!-- 行 2：SpaceX -->\n                <tr data-category=\"launch prime\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">SpaceX (未上市)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">全球商业航天绝对霸主</div>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">重型可复用火箭 + Starlink</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">Falcon 9 (年 130+ 次)<br><span class=\"text-xs text-slate-500\">Starship 100t+ 重型</span></td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-emerald-500/15 text-emerald-700 dark:text-emerald-400\">全产业链极致闭环</span>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">估值 &gt;$350B<br><span class=\"text-xs text-slate-500\">年营收 &gt;$15B</span></td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>对比启示：</strong>规模与复用成本遥遥领先，但其 Starlink 业务与商业星座客户存在直接利益冲突，为 RKLB 创造第二供应商红利。\n                  </td>\n                </tr>\n\n                <!-- 行 3：Northrop Grumman / Lockheed Martin -->\n                <tr data-category=\"prime\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Northrop / Lockheed (NOC / LMT)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">传统美国防务航天主承包商</div>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">大型军用卫星与重型防务发射</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">ULA Vulcan / Minotaur<br><span class=\"text-xs text-slate-500\">一次性高成本构型</span></td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-500/15 text-slate-600 dark:text-slate-400\">高度依赖多层外包</span>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">航天板块 $12B–$14B<br><span class=\"text-xs text-slate-500\">低个位数增长</span></td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>对比启示：</strong>传统成本加成模式研制周期慢、缺乏火箭复用技术，正逐步被 RKLB 等敏捷商业航天抢占 SDA 与 NSSL 份额。\n                  </td>\n                </tr>\n\n                <!-- 行 4：Firefly Aerospace / Relativity Space -->\n                <tr data-category=\"launch\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Firefly / Relativity Space</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">私募阶段中小型新兴火箭商</div>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">纯火箭发射与月球着陆器</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">Alpha 1t / Terran R 23t<br><span class=\"text-xs text-slate-500\">累计入轨 &lt;10 次</span></td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/15 text-amber-700 dark:text-amber-400\">缺乏稳定硬件现金流</span>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">私募估值 $2B–$4B<br><span class=\"text-xs text-slate-500\">年营收 &lt;$150M</span></td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>对比启示：</strong>发射履历与资金实力远逊于 RKLB，且无大规模卫星分系统现金流造血，抗周期风险能力明显偏弱。\n                  </td>\n                </tr>\n\n                <!-- 行 5：York Space / Terran Orbital -->\n                <tr data-category=\"satellite\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">York Space / Terran Orbital</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">小卫星总线专用制造商</div>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">纯卫星平台批量代工</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-500 dark:text-slate-400\">无自有发射运载工具</td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-indigo-500/15 text-indigo-700 dark:text-indigo-400\">中度整合 (缺发射协同)</span>\n                  </td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">Backlog $0.5B–$2B<br><span class=\"text-xs text-slate-500\">盈利波动较大</span></td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>对比启示：</strong>Terran Orbital 因流动性危机被洛马低价收购，反衬出 RKLB “~$1.0B+ 现金 + 自有发射 + 核心部件自产”的强大护城河。\n                  </td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n\n        <!-- 互动图表 3：全球商业轨道发射频次地位 & RKLB 毛利率结构扩张轨迹 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">非 SpaceX 阵营商业轨道发射累计成功次数对比 & RKLB 长期毛利率爬坡</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">Rocket Lab 独占西方私营小型商业发射逾 80% 市场份额，规模效应推动毛利率由 2022 年 ~9% 跃升至 32%–35%+ 目标</p>\n            </div>\n            <span class=\"text-xs font-semibold text-crimson-600 dark:text-crimson-300 bg-crimson-600/15 px-2.5 py-1 rounded\">西方商业火箭发射绝对第二极</span>\n          </div>\n          <div class=\"relative h-64 w-full\">\n            <canvas id=\"compLaunchChart\"></canvas>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           04. 财务健康度与估值体系 (Financial Health & Valuation)\n      ========================================================= -->\n      <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation Framework</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">04. 财务健康度与估值体系：研发达峰拐点、充沛流动性与 SOTP 重估</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">核心看点：~$1.0B+ 现金储备无忧 · 2026–2027 迎 EBITDA 与 FCF 转正</span>\n        </div>\n\n        <!-- 1. 财务健康度剖析三支柱卡片 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase tracking-wider\">Margin Expansion</div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white mt-1\">高毛利太空系统 + Electron 摊薄固定成本</h3>\n            <div class=\"mt-2.5 text-2xl font-extrabold font-mono text-slate-900 dark:text-white\">GAAP GM ~9% → 32%–35%+</div>\n            <p class=\"mt-2 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n              随着 Space Systems 营收占比稳定在 70% 以上且垂直自产率提升，叠加 Electron 年发射频次突破 20+ 次有效摊薄发射场与工厂固定折旧，公司 GAAP 毛利率已从 2022 年的 9% 大幅改善至 2025/2026 的 <strong>28%–33%</strong>，长期稳态目标直指 <strong>35%–40%</strong>。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-crimson-600 dark:text-crimson-400 uppercase tracking-wider\">R&D Peak & Liquidity</div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white mt-1\">~$1.0B+ 流动性全额覆盖 Neutron 商业化</h3>\n            <div class=\"mt-2.5 text-2xl font-extrabold font-mono text-slate-900 dark:text-white\">Cash ~$1.0B+ · 研发占比见顶</div>\n            <p class=\"mt-2 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n              通过可转债与资本结构优化，公司账面持有约 <strong>$1.0B+</strong> 现金及有价证券，足以完全覆盖 Neutron 研发、Archimedes 发动机试车与 Wallops 3号发射台基建，彻底消除困境股权融资（Distress Dilution）风险；伴随 Neutron 从重研发转向商业飞行，研发费用率将迎来显著下行拐点。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-accent-600 dark:text-accent-400 uppercase tracking-wider\">SOTP Valuation Paradigm</div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white mt-1\">从 EV/Sales 向分部加总（SOTP）与 FCF 演进</h3>\n            <div class=\"mt-2.5 text-2xl font-extrabold font-mono text-slate-900 dark:text-white\">太空系统基石 + Neutron 看涨期权</div>\n            <p class=\"mt-2 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n              机构估值正加速从单一概念 EV/Sales 切换至 <strong>SOTP（分部加总估值法）</strong>：① <strong>Space Systems</strong> 具备可预测军工与商业积压订单，可对标高成长防务科技给予 6x–8x 远期销售额或 22x–25x 稳态 EBITDA；② <strong>Launch + 未来自有太空应用星座</strong> 则提供高弹性看涨期权溢价。\n            </p>\n          </div>\n        </div>\n\n        <!-- 2. 交互图表 4：2022–2027E GAAP 毛利率 (%) 攀升与 Adjusted EBITDA ($M) 盈利转正双轴图 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2022–2027E GAAP 毛利率（%）扩张与 Adjusted EBITDA（$M）盈利拐点轨迹</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">随 Neutron 研发投入强度见顶回落及高毛利卫星系统放量，公司跨越盈亏平衡线迈向强自由现金流</p>\n            </div>\n            <span class=\"text-xs font-mono font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2.5 py-1 rounded\">2026E–2027E 迎 EBITDA 与 FCF 强势转正</span>\n          </div>\n          <div class=\"relative h-72 w-full\">\n            <canvas id=\"profitabilityChart\"></canvas>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           05. 投资决策与三情景推演 (Investment Thesis & Scenarios)\n      ========================================================= -->\n      <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-crimson-600 dark:text-crimson-400\">Section 05 · Investment Thesis & Scenario Matrix</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">05. 投资决策与三情景估值推演：卡位全球商业航天稀缺核心复利</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">核心定位：“太空基础设施第二极” · 三阶段价值释放曲线</span>\n        </div>\n\n        <!-- 核心看多理由 (Core Bull Thesis) 卡片 -->\n        <div class=\"bg-gradient-to-br from-navy-900 to-slate-800 text-white rounded-2xl p-6 sm:p-8 border border-slate-700 shadow-sm\">\n          <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n            <span class=\"px-3 py-1 rounded-full bg-crimson-600/25 border border-crimson-500/40 text-crimson-300 text-xs font-bold\">CORE BULL THESIS · 三重结构性红利共振</span>\n            <span class=\"text-xs font-mono text-slate-400\">组合定位：高成长硬科技 / 商业航天核心底仓 (3%–6%)</span>\n          </div>\n          <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5 text-xs sm:text-sm\">\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"text-crimson-300 font-bold mb-1.5\">01 · 地缘与星座组网催生“非 SpaceX 刚需”</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                无论美国国防部（SDA 扩散型低轨架构、NSSL 国家安全发射）还是 Amazon Kuiper 等商业巨型星座，均无法接受将 100% 发射与卫星产能押注于单一供应商。Rocket Lab 是西方世界唯一兼具已验证轨道飞行史与工程交付能力的第二选择。\n              </p>\n            </div>\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"text-teal-300 font-bold mb-1.5\">02 · “先卖铲子再建网络”的三步走闭环</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                第一步用高频发射占领入口，第二步用垂直整合卫星平台与核心部件赚取高粘性硬件利润（目前正处此阶段爆发期），第三步利用 Neutron 自研复用运力低成本部署自有太空数据/通信应用星座，打开类似 Starlink 的高毛利经常性服务天花板。\n              </p>\n            </div>\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"text-amber-300 font-bold mb-1.5\">03 · 研发达峰后的经营杠杆爆发</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                过去三年 Neutron 每年消耗数千万美元密集研发开支，掩盖了 Electron 与 Space Systems 真实的盈利能力。一旦 Neutron 转入商业常态化发射，研发费用率骤降与高单价发射收入共振将带来极具爆发力的 EBITDA 与 FCF 释放。\n              </p>\n            </div>\n          </div>\n        </div>\n\n        <!-- 三情景估值与里程碑推演矩阵 (Bull / Base / Bear) -->\n        <div>\n          <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">2027E 远期三情景估值与里程碑推演矩阵（Bull / Base / Bear）</h3>\n          <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n            <!-- 乐观牛市 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n              <div>\n                <div class=\"flex items-center justify-between mb-2\">\n                  <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">乐观牛市 (Bull Case)</span>\n                  <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">概率：30%</span>\n                </div>\n                <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">2027E 营收 ~$1.60B+ <span class=\"text-xs font-normal text-slate-500\">(EV/Sales ~10x)</span></div>\n                <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                  <strong>核心里程碑假设：</strong>Neutron 顺利实现首飞并迅速在 2027 年完成 <strong>4–6 次商业与 NSSL 发射</strong>；Electron 保持 24+ 次/年高频交付；Space Systems 斩获 SDA Tranche 3 大单且毛利率突破 <strong>38%</strong>，全年 Adjusted EBITDA 达 <strong>$260M+</strong>，自研太空应用服务正式发布。\n                </p>\n              </div>\n              <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n                估值逻辑：全栈平台稀缺溢价 + 强劲自由现金流重估\n              </div>\n            </div>\n\n            <!-- 基准情景 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-crimson-600 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n              <div>\n                <div class=\"flex items-center justify-between mb-2\">\n                  <span class=\"px-2.5 py-0.5 rounded bg-crimson-600/15 text-crimson-700 dark:text-crimson-300 text-xs font-bold\">基准情景 (Base Case)</span>\n                  <span class=\"font-mono text-xs font-bold text-crimson-600 dark:text-crimson-300\">概率：50%</span>\n                </div>\n                <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">2027E 营收 ~$1.35B <span class=\"text-xs font-normal text-slate-500\">(EV/Sales ~7.5x)</span></div>\n                <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                  <strong>核心里程碑假设：</strong>Neutron 在 2027 年实现 <strong>2–3 次商业发射</strong>，Space Systems 按期高质量交付 SDA 卫星并维持 <strong>34%–36%</strong> 毛利率，Electron 年发射稳定在 20–22 次，全公司 Adjusted EBITDA 稳步提升至 <strong>~$155M</strong> 且自由现金流全面转正。\n                </p>\n              </div>\n              <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-crimson-600 dark:text-crimson-300\">\n                估值逻辑：内生高增兑现 + 跨越盈利盈亏平衡点\n              </div>\n            </div>\n\n            <!-- 悲观熊市 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n              <div>\n                <div class=\"flex items-center justify-between mb-2\">\n                  <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">悲观熊市 (Bear Case)</span>\n                  <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n                </div>\n                <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">2027E 营收 ~$1.05B <span class=\"text-xs font-normal text-slate-500\">(EV/Sales ~4.5x)</span></div>\n                <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                  <strong>核心里程碑假设：</strong>Neutron 遭遇工程测试或发射台审批进一步推迟（2027 仅完成 1 次演示飞行），叠加美国国防预算拨款节奏放缓或 Electron 出现单次发射异常导致停飞排查，全公司盈利转正延后至 2028 年。\n                </p>\n              </div>\n              <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n                防守安全垫：&gt;$1.1B 在手订单 + ~$1.0B+ 账面现金护航\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           06. 风险配置与季度跟踪 KPI 核查清单 (Risk & KPI Checklist)\n      ========================================================= -->\n      <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Risk Allocation & Quarterly KPI Checklist</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">06. 风险配置与季度基本面跟踪 KPI 交互核查清单</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">六大机构核心跟踪指标 · 勾选状态自动本地持久化</span>\n        </div>\n\n        <!-- 1. 四大核心风险因素与对冲策略 -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · Neutron 研制与首飞进度延期风险</span>\n              <span class=\"text-xs font-mono text-rose-500 font-semibold\">关注度：极高</span>\n            </div>\n            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">新型火箭首飞工程不确定性与研发成本超支</h4>\n            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n              大型低温推进剂火箭首飞历来存在高工程难度；任何发动机试车或发射场验收延期均可能推迟高单价发射收入确认，引发高 Beta 成长股估值剧烈波动。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · Electron 发射任务异常与停飞风险</span>\n              <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n            </div>\n            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">单次发射失利引发的 FAA 调查与季度收入递延</h4>\n            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n              航天发射容错率极低，若 Electron 发生任务异常将触发 FAA 停飞审查（通常持续 4–8 周），导致当季 2–3 发计划递延至后续季度确认收入。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · SpaceX 拼车降价与重型运力挤压</span>\n              <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中高</span>\n            </div>\n            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">Falcon 9 Transporter 拼车与 Starship 长期成本优势</h4>\n            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n              SpaceX 拼车服务在价格敏感型微纳卫星市场具备极低单公斤报价；RKLB 需持续通过“专享轨道倾角定制 + 军工高安全壁垒”维持 Electron 与 Neutron 溢价。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 美国国防预算拨款节奏与高估值波动</span>\n              <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n            </div>\n            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">国会持续决议（CR）对 SDA 订单落地时点的扰动</h4>\n            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n              国防航天订单受美国国会预算审批影响，大型合同授予存在季度间波动性，建议投资者采用“核心底仓 + 逢回撤分批布局”策略平滑波动。\n            </p>\n          </div>\n        </div>\n\n        <!-- 2. 季度基本面跟踪 KPI 交互核查清单 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">Rocket Lab 财报季六大核心 KPI 验真台</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">点击勾选最新季报已验证达标的指标，实时评估基本面兑现进度（状态自动保存至 localStorage）</p>\n            </div>\n            <div class=\"flex items-center space-x-2 no-print\">\n              <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-crimson-600/15 text-crimson-700 dark:text-crimson-300 text-xs font-bold\">已核查 4 / 6 项 (67%)</span>\n              <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n            </div>\n          </div>\n\n          <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5 mt-4\" id=\"kpi-checklist\">\n            <!-- KPI 1 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"rklb-kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E11D48] focus:ring-crimson-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. Neutron Archimedes 发动机试车与发射台里程碑</span>\n                  <span class=\"text-[11px] font-mono text-crimson-600 dark:text-crimson-300 font-semibold shrink-0\">核心估值催化剂</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  跟踪 Archimedes 全流量分级燃烧发动机热试车频次、级间静态点火及 Wallops LC-3 发射台交付时间表。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 2 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"rklb-kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E11D48] focus:ring-crimson-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. Space Systems 业务毛利率稳居 35%+</span>\n                  <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">盈利质量基石</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  验证卫星总线批产交付与高毛利太阳翼/分离器组件放量后，太空系统板块 GAAP/Non-GAAP 毛利率扩展情况。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 3 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"rklb-kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E11D48] focus:ring-crimson-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 单季 Electron / HASTE 发射频次 ≥ 5–6 次</span>\n                  <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold shrink-0\">发射规模效应锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  核查单季成功入轨发射次数是否达到 5–6 发以上（对应年化 20–24+ 发），从而推动发射板块毛利率向 30%+ 迈进。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 4 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"rklb-kpi-4\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E11D48] focus:ring-crimson-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 在手订单 Backlog 扩张与 SDA 新批次授标</span>\n                  <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">增长能见度指标</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  追踪季度新增订单账面出货比（Book-to-Bill &gt; 1.0x）以及美国太空发展局（SDA）新一批次卫星及 Neutron 商业合同签约。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 5 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"rklb-kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E11D48] focus:ring-crimson-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 研发费用（R&D）占营收比重阶梯式下降</span>\n                  <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">经营杠杆指标</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  观察随着 Neutron 一次性非经常性工程研制费用（NRE）度过峰值，R&D 费用率是否如期向 20% 以下收敛。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 6 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"rklb-kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#E11D48] focus:ring-crimson-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. Adjusted EBITDA 转正及自由现金流收窄节奏</span>\n                  <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">现金流拐点锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  核查单季 Adjusted EBITDA 迈过盈亏平衡线进度及经营性现金流改善情况，验证无额外股权摊薄的自我造血能力。\n                </p>\n              </div>\n            </label>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           页脚免责声明 (Disclaimer Footer)\n      ========================================================= -->\n      <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n        <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n          <span>Rocket Lab USA, Inc. (NASDAQ: RKLB) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n          <span>数据基准：2026 年 11 月 (FY2025 财报及 FY26E–27E 市场一致预期)</span>\n        </div>\n        <p class=\"leading-relaxed\">\n          <strong>免责声明：</strong>本深度研究报告基于公司公开披露财报（10-K / 10-Q）、美国国防部与 NASA 公开招标文件、全球商业发射数据库及机构估值模型整理生成，旨在提供结构化的商业模式与投资逻辑参考。文中涉及的 2026E–2027E 营收与盈利预测、Neutron 商业发射节奏假设以及三情景估值推演均基于特定产业假设，不构成任何具体的证券买卖建议、要约或投资承诺。商业航天属于高技术壁垒与高波动赛道，投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n        </p>\n      </footer>\n\n    </div>\n  </main>\n\n  <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n  <script>\n    // ==========================================\n    // 1. 亮色 / 深色模式切换（同步重绘所有 Chart.js 图表）\n    // ==========================================\n    function toggleTheme() {\n      const html = document.documentElement;\n      html.classList.toggle('dark');\n      updateChartsTheme();\n    }\n\n    // ==========================================\n    // 2. 移动端抽屉菜单切换\n    // ==========================================\n    function toggleMobileMenu() {\n      const drawer = document.getElementById('mobile-drawer');\n      drawer.classList.toggle('hidden');\n    }\n\n    // ==========================================\n    // 3. 阅读进度条与侧边导航滚动联动高亮\n    // ==========================================\n    const sections = document.querySelectorAll('section[id]');\n    const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n    window.addEventListener('scroll', () => {\n      const scrollTop = window.scrollY;\n      const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n      const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n      document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n      let currentId = 'sec-biz';\n      sections.forEach(sec => {\n        const top = sec.offsetTop - 160;\n        if (scrollTop >= top) {\n          currentId = sec.getAttribute('id');\n        }\n      });\n\n      navLinks.forEach(link => {\n        link.classList.remove('active');\n        const numSpan = link.querySelector('span span');\n        if (numSpan) {\n          numSpan.classList.remove('text-crimson-400');\n          numSpan.classList.add('text-slate-500');\n        }\n        if (link.dataset.target === currentId) {\n          link.classList.add('active');\n          if (numSpan) {\n            numSpan.classList.remove('text-slate-500');\n            numSpan.classList.add('text-crimson-400');\n          }\n        }\n      });\n    });\n\n    // ==========================================\n    // 4. 同行竞争格局矩阵筛选器\n    // ==========================================\n    function filterCompetitors(category) {\n      document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n        if (btn.dataset.filter === category) {\n          btn.classList.add('bg-crimson-600', 'text-white', 'font-semibold', 'shadow-sm');\n          btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n        } else {\n          btn.classList.remove('bg-crimson-600', 'text-white', 'font-semibold', 'shadow-sm');\n          btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n        }\n      });\n\n      const rows = document.querySelectorAll('#comp-table-body tr');\n      rows.forEach(row => {\n        const rowCat = row.dataset.category || '';\n        if (category === 'all' || rowCat === 'core' || rowCat.includes(category)) {\n          row.style.display = '';\n        } else {\n          row.style.display = 'none';\n        }\n      });\n    }\n\n    // ==========================================\n    // 5. KPI 核查清单状态持久化与计数更新\n    // ==========================================\n    const KPI_STORAGE_KEY = 'rklb_research_kpi_state_v1';\n\n    function loadKpiChecklist() {\n      try {\n        const saved = localStorage.getItem(KPI_STORAGE_KEY);\n        if (saved) {\n          const stateMap = JSON.parse(saved);\n          document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n            if (typeof stateMap[cb.id] === 'boolean') {\n              cb.checked = stateMap[cb.id];\n            }\n          });\n        }\n      } catch (e) {\n        // 忽略存储权限异常\n      }\n      updateKpiChecklist();\n    }\n\n    function updateKpiChecklist() {\n      const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n      const total = checkboxes.length;\n      let checkedCount = 0;\n      const stateMap = {};\n\n      checkboxes.forEach(cb => {\n        stateMap[cb.id] = cb.checked;\n        if (cb.checked) checkedCount++;\n      });\n\n      const pct = Math.round((checkedCount / total) * 100);\n      document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n      try {\n        localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n      } catch (e) {\n        // 忽略存储权限异常\n      }\n    }\n\n    function resetKpiChecklist() {\n      document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n        cb.checked = false;\n      });\n      updateKpiChecklist();\n    }\n\n    // ==========================================\n    // 6. Chart.js 四大交互数据图表与主题自适应\n    // ==========================================\n    let bizChartInstance = null;\n    let radarChartInstance = null;\n    let compLaunchChartInstance = null;\n    let profitabilityChartInstance = null;\n    let currentBizMode = 'trajectory';\n\n    function getChartColors() {\n      const isDark = document.documentElement.classList.contains('dark');\n      return {\n        text: isDark ? '#CBD5E1' : '#475569',\n        grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n        radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n      };\n    }\n\n    function initBizChart() {\n      const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n      const colors = getChartColors();\n\n      // View A: 2021–2027E Revenue Mix Stacked Bar (Space Systems vs. Launch Services) + Gross Margin Line\n      const trajConfig = {\n        type: 'bar',\n        data: {\n          labels: ['2021', '2022', '2023', '2024', '2025', '2026E', '2027E'],\n          datasets: [\n            {\n              type: 'bar',\n              label: 'Space Systems 太空系统营收 ($M)',\n              data: [23, 150, 173, 311, 434, 650, 910],\n              backgroundColor: '#0D9488',\n              borderRadius: 4,\n              stack: 'rev',\n              barThickness: 28,\n              yAxisID: 'y'\n            },\n            {\n              type: 'bar',\n              label: 'Launch Services 发射服务营收 ($M)',\n              data: [39, 61, 72, 125, 168, 250, 440],\n              backgroundColor: '#E11D48',\n              borderRadius: 4,\n              stack: 'rev',\n              barThickness: 28,\n              yAxisID: 'y'\n            },\n            {\n              type: 'line',\n              label: 'GAAP 综合毛利率 (%)',\n              data: [-3.2, 9.0, 21.0, 26.6, 29.8, 32.5, 35.2],\n              borderColor: '#F59E0B',\n              backgroundColor: '#F59E0B',\n              borderWidth: 3,\n              pointRadius: 5,\n              pointHoverRadius: 7,\n              tension: 0.25,\n              yAxisID: 'y1'\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => ctx.dataset.yAxisID === 'y'\n                  ? `${ctx.dataset.label}: $${ctx.parsed.y}M`\n                  : `GAAP 综合毛利率: ${ctx.parsed.y.toFixed(1)}%`\n              }\n            }\n          },\n          scales: {\n            x: {\n              stacked: true,\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              stacked: true,\n              type: 'linear',\n              position: 'left',\n              max: 1500,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'M' }\n            },\n            y1: {\n              type: 'linear',\n              position: 'right',\n              min: -10,\n              max: 45,\n              grid: { drawOnChartArea: false },\n              ticks: { color: '#F59E0B', font: { size: 11, weight: '600' }, callback: v => v + '%' }\n            }\n          }\n        }\n      };\n\n      // View B: Backlog Breakdown & Vertical Supply Chain Self-Sufficiency\n      const backlogConfig = {\n        type: 'bar',\n        data: {\n          labels: [\n            '在手订单 Backlog 结构 (>$1.1B)',\n            'Space Systems 客户结构 (国防 vs 商业)',\n            '卫星核心分系统内部自给率 (%)'\n          ],\n          datasets: [\n            {\n              label: '主导份额 (太空系统 70% / 国防机构 55% / 内部自产 72%)',\n              data: [70, 55, 72],\n              backgroundColor: '#0D9488',\n              borderRadius: 5,\n              barThickness: 28\n            },\n            {\n              label: '第二支柱 (发射服务 30% / 商业星座 45% / 外部采购 28%)',\n              data: [30, 45, 28],\n              backgroundColor: '#E11D48',\n              borderRadius: 5,\n              barThickness: 28\n            }\n          ]\n        },\n        options: {\n          indexAxis: 'y',\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `${ctx.dataset.label.split(' (')[0]}: ${ctx.parsed.x}%`\n              }\n            }\n          },\n          scales: {\n            x: {\n              stacked: true,\n              max: 100,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n            },\n            y: {\n              stacked: true,\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      };\n\n      if (bizChartInstance) bizChartInstance.destroy();\n      bizChartInstance = new Chart(ctx, currentBizMode === 'trajectory' ? trajConfig : backlogConfig);\n    }\n\n    function switchBizChart(mode) {\n      currentBizMode = mode;\n      const btnTraj = document.getElementById('btn-chart-traj');\n      const btnBacklog = document.getElementById('btn-chart-backlog');\n      const titleEl = document.getElementById('biz-chart-title');\n      const subEl = document.getElementById('biz-chart-sub');\n\n      if (mode === 'trajectory') {\n        btnTraj.className = 'px-3 py-1.5 rounded-md font-semibold bg-white dark:bg-navy-700 text-crimson-600 dark:text-crimson-300 shadow-sm transition';\n        btnBacklog.className = 'px-3 py-1.5 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n        titleEl.textContent = '2021–2027E 营收结构演进（Space Systems vs. Launch Services 堆叠 + GAAP 毛利率）';\n        subEl.textContent = '营收从 2021 年 $62M 跃升至 2026E ~$900M 及 2027E ~$1.35B（含 Neutron 商业化放量），毛利率迈向 35%+';\n      } else {\n        btnBacklog.className = 'px-3 py-1.5 rounded-md font-semibold bg-white dark:bg-navy-700 text-crimson-600 dark:text-crimson-300 shadow-sm transition';\n        btnTraj.className = 'px-3 py-1.5 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n        titleEl.textContent = '在手订单 Backlog 结构、国防/商业客户占比与垂直供应链自给拆解';\n        subEl.textContent = '超 $1.1B 积压订单中约 70% 为高粘性太空系统合同，卫星核心硬件自产率逾 72%';\n      }\n      initBizChart();\n    }\n\n    function initRadarChart() {\n      const ctx = document.getElementById('moatRadarChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (radarChartInstance) radarChartInstance.destroy();\n      radarChartInstance = new Chart(ctx, {\n        type: 'radar',\n        data: {\n          labels: [\n            '发射频次与轨道可靠性',\n            '端到端卫星制造与垂直整合',\n            '火箭复用技术与成本效率',\n            '国防安全资质与政府准入',\n            '资本效率与商业化执行力'\n          ],\n          datasets: [\n            {\n              label: 'Rocket Lab (RKLB)',\n              data: [8.6, 9.4, 8.2, 9.2, 9.1],\n              borderColor: '#E11D48',\n              backgroundColor: 'rgba(225, 29, 72, 0.24)',\n              pointBackgroundColor: '#E11D48',\n              borderWidth: 2.5\n            },\n            {\n              label: 'SpaceX (行业标杆)',\n              data: [10.0, 9.8, 10.0, 9.8, 9.6],\n              borderColor: '#0D9488',\n              backgroundColor: 'rgba(13, 148, 136, 0.14)',\n              pointBackgroundColor: '#0D9488',\n              borderWidth: 1.8\n            },\n            {\n              label: '传统航天巨头 (ULA / Arianespace)',\n              data: [7.2, 8.5, 4.0, 9.5, 5.2],\n              borderColor: '#3B82F6',\n              backgroundColor: 'rgba(59, 130, 246, 0.10)',\n              pointBackgroundColor: '#3B82F6',\n              borderWidth: 1.5,\n              borderDash: [4, 4]\n            },\n            {\n              label: '新兴中小型火箭商 (Firefly / Relativity)',\n              data: [4.2, 3.8, 5.5, 5.4, 4.8],\n              borderColor: '#94A3B8',\n              backgroundColor: 'rgba(148, 163, 184, 0.10)',\n              pointBackgroundColor: '#94A3B8',\n              borderWidth: 1.5,\n              borderDash: [2, 2]\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n            }\n          },\n          scales: {\n            r: {\n              min: 0,\n              max: 10,\n              ticks: { display: false, stepSize: 2 },\n              grid: { color: colors.grid },\n              angleLines: { color: colors.radarAngle },\n              pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function initCompLaunchChart() {\n      const ctx = document.getElementById('compLaunchChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (compLaunchChartInstance) compLaunchChartInstance.destroy();\n      compLaunchChartInstance = new Chart(ctx, {\n        type: 'bar',\n        data: {\n          labels: [\n            'Rocket Lab Electron (累计轨道发射次数)',\n            'Arianespace Vega / Vega-C (欧洲小型火箭)',\n            'Firefly Alpha (美国私营小型火箭)',\n            'Virgin Orbit LauncherOne (已破产退出)',\n            'Astra Rocket 3 (已退市转型)'\n          ],\n          datasets: [\n            {\n              label: '累计成功入轨发射次数 (次)',\n              data: [72, 22, 4, 4, 2],\n              backgroundColor: [\n                '#E11D48',\n                '#0D9488',\n                '#3B82F6',\n                '#94A3B8',\n                '#CBD5E1'\n              ],\n              borderRadius: 6,\n              barThickness: 22\n            }\n          ]\n        },\n        options: {\n          indexAxis: 'y',\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `累计成功轨道发射: ${ctx.parsed.x} 次`\n              }\n            }\n          },\n          scales: {\n            x: {\n              max: 85,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => v + ' 次' }\n            },\n            y: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function initProfitabilityChart() {\n      const ctx = document.getElementById('profitabilityChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (profitabilityChartInstance) profitabilityChartInstance.destroy();\n      profitabilityChartInstance = new Chart(ctx, {\n        type: 'bar',\n        data: {\n          labels: ['2022', '2023', '2024', '2025', '2026E', '2027E'],\n          datasets: [\n            {\n              type: 'bar',\n              label: 'Adjusted EBITDA ($M)',\n              data: [-34, -91, -97, -58, 12, 155],\n              backgroundColor: (ctx) => ctx.raw >= 0 ? '#10B981' : '#F43F5E',\n              borderRadius: 6,\n              barThickness: 32,\n              yAxisID: 'y'\n            },\n            {\n              type: 'line',\n              label: 'GAAP 毛利率 Gross Margin (%)',\n              data: [9.0, 21.0, 26.6, 29.8, 32.5, 35.2],\n              borderColor: '#0D9488',\n              backgroundColor: '#0D9488',\n              borderWidth: 3,\n              pointRadius: 5,\n              pointHoverRadius: 7,\n              tension: 0.25,\n              yAxisID: 'y1'\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => ctx.dataset.yAxisID === 'y'\n                  ? `Adjusted EBITDA: ${ctx.parsed.y >= 0 ? '+$' + ctx.parsed.y : '-$' + Math.abs(ctx.parsed.y)}M`\n                  : `GAAP 毛利率: ${ctx.parsed.y.toFixed(1)}%`\n              }\n            }\n          },\n          scales: {\n            x: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              type: 'linear',\n              position: 'left',\n              min: -130,\n              max: 200,\n              grid: { color: colors.grid },\n              ticks: {\n                color: colors.text,\n                font: { size: 11 },\n                callback: v => (v >= 0 ? '$' + v : '-$' + Math.abs(v)) + 'M'\n              }\n            },\n            y1: {\n              type: 'linear',\n              position: 'right',\n              min: 0,\n              max: 45,\n              grid: { drawOnChartArea: false },\n              ticks: { color: '#0D9488', font: { size: 11, weight: '600' }, callback: v => v + '%' }\n            }\n          }\n        }\n      });\n    }\n\n    function updateChartsTheme() {\n      initBizChart();\n      initRadarChart();\n      initCompLaunchChart();\n      initProfitabilityChart();\n    }\n\n    window.addEventListener('DOMContentLoaded', () => {\n      loadKpiChecklist();\n      initBizChart();\n      initRadarChart();\n      initCompLaunchChart();\n      initProfitabilityChart();\n    });\n  </script>\n</body>\n</html>"};
